/**
 * Workflow Worker
 *
 * Polls for stalled workflow runs and resumes them.
 * Enables distributed workflow execution across multiple pods.
 */
import { logger as baseLogger, sleep } from "../../utils/index.js";
import { hasWorkerSupport } from "../backends/types.js";
import { generateId } from "../types.js";
import { CONFIG_INVALID, ORCHESTRATION_ERROR } from "../../errors/index.js";
import { runWithWorkflowSourceIntegrationPolicy } from "../source-integration-policy.js";
const logger = baseLogger.component("workflow-worker");
/** Default interval between poll cycles */
const DEFAULT_POLL_INTERVAL_MS = 5_000;
/** Default threshold after which a run is considered stalled */
const DEFAULT_STALLED_THRESHOLD_MS = 60_000;
/** Maximum time stop() waits for in-flight resumes before abandoning them */
const WORKER_STOP_TIMEOUT_MS = 30_000;
/** Implement workflow worker. */
export class WorkflowWorker {
    config;
    status = "idle";
    pollTimeout;
    activeResumes = new Set();
    stats;
    constructor(config) {
        // Validate backend supports worker features
        if (!hasWorkerSupport(config.backend)) {
            throw CONFIG_INVALID.create({
                detail: "Backend does not support worker features. " +
                    "Required methods: enqueue, dequeue, acknowledge, acquireLock, releaseLock, " +
                    "findStalledRuns, claimStalledRun, updateRunIfStatusAndWorker, " +
                    "saveCheckpointIfStatusAndWorker, savePendingApprovalIfStatusAndWorker. " +
                    "Use RedisBackend with worker support enabled.",
            });
        }
        this.config = {
            pollInterval: DEFAULT_POLL_INTERVAL_MS,
            stalledThreshold: DEFAULT_STALLED_THRESHOLD_MS,
            concurrency: 3,
            workerId: generateId("worker"),
            debug: false,
            ...config,
        };
        this.stats = {
            status: "idle",
            workerId: this.config.workerId,
            pollCount: 0,
            resumeCount: 0,
            errorCount: 0,
        };
    }
    /**
     * Start the worker polling loop
     */
    start() {
        if (this.status === "running") {
            throw ORCHESTRATION_ERROR.create({ detail: "Worker is already running" });
        }
        this.status = "running";
        this.stats.status = "running";
        this.stats.startedAt = new Date();
        if (this.config.debug) {
            logger.info(`Started worker ${this.config.workerId}`);
        }
        // Start polling loop
        this.scheduleNextPoll();
    }
    /**
     * Stop the worker gracefully
     */
    async stop() {
        if (this.status !== "running") {
            return;
        }
        this.status = "stopping";
        this.stats.status = "stopping";
        if (this.config.debug) {
            logger.info(`Stopping worker ${this.config.workerId}...`);
        }
        // Clear scheduled poll
        if (this.pollTimeout) {
            clearTimeout(this.pollTimeout);
            this.pollTimeout = undefined;
        }
        // Wait for active resumes to complete, but bound the wait: a hung
        // resumeFn (e.g. an unreachable backend) must not block shutdown forever.
        const stopDeadline = Date.now() + WORKER_STOP_TIMEOUT_MS;
        while (this.activeResumes.size > 0) {
            if (Date.now() >= stopDeadline) {
                logger.warn(`[WorkflowWorker] Stop timed out with ${this.activeResumes.size} active resume(s); abandoning wait`);
                break;
            }
            if (this.config.debug) {
                logger.debug(`[WorkflowWorker] Waiting for ${this.activeResumes.size} active resumes to complete`);
            }
            await sleep(1000);
        }
        this.status = "stopped";
        this.stats.status = "stopped";
        if (this.config.debug) {
            logger.info(`Worker ${this.config.workerId} stopped`);
        }
    }
    /**
     * Get worker statistics
     */
    getStats() {
        return { ...this.stats };
    }
    /**
     * Get worker ID
     */
    getWorkerId() {
        return this.config.workerId;
    }
    /**
     * Schedule the next poll
     */
    scheduleNextPoll() {
        if (this.status !== "running") {
            return;
        }
        this.pollTimeout = setTimeout(async () => {
            // poll() has its own try/catch, but guard here too: if it ever rejects
            // (or a future refactor removes that guard) the finally still reschedules
            // so the loop can't silently die and leave the worker alive-but-idle.
            try {
                await this.poll();
            }
            catch (error) {
                this.recordError(error);
                logger.error("Unhandled poll error:", error);
            }
            finally {
                this.scheduleNextPoll();
            }
        }, this.config.pollInterval);
    }
    /**
     * Record an error in stats
     */
    recordError(error) {
        this.stats.errorCount++;
        this.stats.lastErrorAt = new Date();
        this.stats.lastError = error instanceof Error ? error.message : String(error);
    }
    /**
     * Poll for stalled workflows and resume them
     */
    async poll() {
        if (this.status !== "running") {
            return;
        }
        this.stats.pollCount++;
        this.stats.lastPollAt = new Date();
        try {
            // Backend is validated in constructor to have worker support. Call the
            // methods on the backend so implementations keep their receiver.
            const backend = this.config.backend;
            // Find stalled runs
            const stalledRuns = await backend.findStalledRuns(this.config.stalledThreshold);
            if (stalledRuns.length === 0) {
                return;
            }
            if (this.config.debug) {
                logger.info(`Found ${stalledRuns.length} stalled runs`);
            }
            // Try to claim and resume stalled runs (up to concurrency limit)
            const availableSlots = this.config.concurrency - this.activeResumes.size;
            for (const run of stalledRuns.slice(0, availableSlots)) {
                // Skip if already being resumed by this worker
                if (this.activeResumes.has(run.id)) {
                    continue;
                }
                // Try to claim the run
                const claimed = await backend.claimStalledRun(run.id, this.config.workerId, this.config.stalledThreshold);
                if (claimed) {
                    this.resumeInBackground(run);
                }
            }
        }
        catch (error) {
            this.recordError(error);
            logger.error(`Poll error:`, error);
        }
    }
    /**
     * Resume a workflow in the background
     */
    resumeInBackground(run) {
        this.activeResumes.add(run.id);
        void (async () => {
            try {
                if (this.config.debug) {
                    logger.info(`Resuming stalled run ${run.id}`);
                }
                await runWithWorkflowSourceIntegrationPolicy(run, () => this.config.resumeFn(run.id, this.config.workerId));
                this.stats.resumeCount++;
                if (this.config.debug) {
                    logger.info(`Successfully resumed run ${run.id}`);
                }
            }
            catch (error) {
                this.recordError(error);
                logger.error(`Failed to resume run ${run.id}:`, error);
            }
            finally {
                this.activeResumes.delete(run.id);
            }
        })();
    }
}
/**
 * Create a workflow worker
 */
export function createWorkflowWorker(config) {
    return new WorkflowWorker(config);
}
